import{_ as a,o as s,c as i,a2 as t}from"./chunks/framework.mRCPFc5l.js";const k=JSON.parse('{"title":"Closeout And Versioning","description":"","frontmatter":{"title":"Closeout And Versioning"},"headers":[],"relativePath":"operations/closeout-and-versioning.md","filePath":"operations/closeout-and-versioning.md","lastUpdated":1787839527000}'),n={name:"operations/closeout-and-versioning.md"};function o(r,e,l,d,h,p){return s(),i("div",null,[...e[0]||(e[0]=[t(`<h1 id="closeout-與版本" tabindex="-1">Closeout 與版本 <a class="header-anchor" href="#closeout-與版本" aria-label="Permalink to &quot;Closeout 與版本&quot;">​</a></h1><h2 id="目的" tabindex="-1">目的 <a class="header-anchor" href="#目的" aria-label="Permalink to &quot;目的&quot;">​</a></h2><p>避免「程式已上 main、但沒有 tag／Release／changelog」或「package.json 超前 tag 被 CI 擋」。</p><p><strong>現行流程是 no-Plane generic long-task。</strong> 不要把 Plane comment／version-label／In Review 當新任務 SOP。</p><h2 id="角色" tabindex="-1">角色 <a class="header-anchor" href="#角色" aria-label="Permalink to &quot;角色&quot;">​</a></h2><table tabindex="0"><thead><tr><th>階段</th><th>誰</th><th>可以做</th><th>禁止</th></tr></thead><tbody><tr><td>實作</td><td>Cursor worker／本機 Cursor</td><td>改碼、測試、commit/push feat、更新 pending notes</td><td>改 <code>frontend/package.json</code> version、<code>npm version</code>、<code>gpr</code>、tag</td></tr><tr><td>發版</td><td>Hermes closeout</td><td><code>closeout:verify</code> → <code>gpr</code> → <code>release:sync-check</code> → fetch origin</td><td>用 bump 腳本繞過 <code>gpr</code></td></tr></tbody></table><p>本 repo <strong>沒有</strong> <code>scripts/bump-version.sh</code>。版本只走 frontend <code>gpr</code>（內部 <code>bump:patch</code>）。</p><h2 id="唯一發版指令" tabindex="-1">唯一發版指令 <a class="header-anchor" href="#唯一發版指令" aria-label="Permalink to &quot;唯一發版指令&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /mnt/data/code/project/StrawCoding/StrawMoneyBook</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fetch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> origin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> main</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --tags</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> frontend</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> closeout:pre</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # notes:check + release:sync-check</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> closeout:verify</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">       # test:node + build:web + closeout:pre</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gpr</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                   # patch：bump + commit + tag + archive notes</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 或 npm run gpr:minor</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> release:sync-check</span></span></code></pre></div><p>Hermes 一鍵（歷史腳本名仍含 Plane，<strong>新任務不要對 Plane 寫狀態</strong>）：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /root/.hermes/scripts/strawmb_closeout.sh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --playwright</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ui-layout</span></span></code></pre></div><p><code>closeout:verify</code> <strong>不含 Playwright</strong>。UI 改動必須另外跑對應 suite（見 <a href="/operations/playwright-app-shell.html">Playwright-App-Shell</a>）。</p><h2 id="pending-notes" tabindex="-1">pending notes <a class="header-anchor" href="#pending-notes" aria-label="Permalink to &quot;pending notes&quot;">​</a></h2><p>檔案：<a href="https://github.com/StrawCoding/StrawMoneyBook/blob/main/release-notes.pending.md" target="_blank" rel="noreferrer"><code>release-notes.pending.md</code></a></p><ul><li>只在 header <code># Pending Release Notes</code> 下加 <code>- </code> 條目</li><li><strong>禁止</strong>手動加 <code>---</code>（<code>gpr</code> archive 才建歷史區）</li><li><code>notes:check</code> 允許空 pending；有產品行為／使用者可見改動時<strong>必須</strong>寫條目，否則 changelog 會漏</li></ul><h2 id="ci-閘門" tabindex="-1">CI 閘門 <a class="header-anchor" href="#ci-閘門" aria-label="Permalink to &quot;CI 閘門&quot;">​</a></h2><p>main 上 <code>frontend/package.json</code> 的 <code>version</code> 必須等於最新 <code>v*</code> tag。人工改版本卻沒跑 <code>gpr</code> → <code>release:sync-check</code> FAIL。</p><h2 id="原生-後端連帶" tabindex="-1">原生／後端連帶 <a class="header-anchor" href="#原生-後端連帶" aria-label="Permalink to &quot;原生／後端連帶&quot;">​</a></h2><ul><li>backend 有改 → <a href="/operations/backend-deployment-and-health.html">Backend-Deployment-And-Health</a>（<code>deploy:copy</code> <strong>然後</strong> <code>docker restart StrawMB</code>）</li><li>FirstBank／華南 Java 有改 → <a href="/operations/android-native-bank-apk.html">Android-Native-Bank-APK</a>（重建 APK）</li></ul><h2 id="引用" tabindex="-1">引用 <a class="header-anchor" href="#引用" aria-label="Permalink to &quot;引用&quot;">​</a></h2><ul><li><a href="https://github.com/StrawCoding/StrawMoneyBook/blob/main/docs/release-checklist.md" target="_blank" rel="noreferrer"><code>docs/release-checklist.md</code></a></li><li><a href="https://github.com/StrawCoding/StrawMoneyBook/blob/main/frontend/package.json" target="_blank" rel="noreferrer"><code>frontend/package.json</code></a> scripts：<code>gpr</code>、<code>closeout:verify</code></li><li><a href="/operations/long-task-worker.html">Long-Task-Worker</a></li></ul>`,21)])])}const g=a(n,[["render",o]]);export{k as __pageData,g as default};
